function [N,mm] = xunhuan( a,T,lj,t0,b,c ) 
%给迭代迈步循环提供函数 
%初始路径移动 
N=8; 
for i=1:4 
 %RGV 每一步移动 
 dT=[0,T(1:3)]; 
 d=dT(abs(a-lj(i))+1); 
 a=lj(i); 
 t0=t0+d; 

 %RGV 为单个奇数CNC 上料 
 M(2*(i-1)+1,1)=t0; 
 t0=t0+T(5); 
 b(2*(lj(i)-1)+1)=1;

29 

 c(2*(lj(i)-1)+1)=t0+T(4); 
 M(2*(i-1)+1,2)=2*(lj(i)-1)+1; 

 %RGV 为单个偶数CNC 上料 
 M(2*(i-1)+2,1)=t0; 
 t0=t0+T(6); 
 b(2*(lj(i)-1)+2)=1; 
 c(2*(lj(i)-1)+2)=t0+T(4); 
 M(2*(i-1)+2,2)=2*(lj(i)-1)+2; 
end 

%多步最优 
while t0<=8*3600 
 [e,f,g,h,] = oneStep( a,dT,T,t0,c );%a,t0,c 改变为f,g,h. 
 e3 = fStep( f,dT,T,g,h,e )'; 
 e3 = reshape(e3,64,4); 
 [minValue,row] = min(e3); 
 [minValue,col] = min(minValue); 
 d=dT(abs(a-col)+1); 
 t0=t0+d; 
 t0 
 a=col; 
 N=N+1; 
 i=a; 
 if t0>c(2*(i-1)+1)&&t0>c(2*(i-1)+2) 
 %[cmin,cind]=min([c(2*(i-1)+1),c(2*(i-1)+2)]); 
 cmin=t0;cind=1; 
 c(2*(i-1)+cind)=cmin+T(4+cind)+T(4); 
 elseif t0<c(2*(i-1)+1)&&t0<c(2*(i-1)+2) 
 [cmin,cind]=min([c(2*(i-1)+1)+T(5),c(2*(i-1)+2)+T(6)]); 
 cmin=cmin-T(4+cind); 
 c(2*(i-1)+cind)=cmin+T(4+cind)+T(4); 
 else 
 [cmin,cind]=min([c(2*(i-1)+1),c(2*(i-1)+2)]); 
 cmin=t0; 
 c(2*(i-1)+cind)=cmin+T(4+cind)+T(4); 
 end 
 M(N,1)=cmin; 
 M(N,2)=2*(i-1)+cind; 
 for i=length(M(:,2))-1:-1:1 
 if M(i,2)==2*(a-1)+cind 
 M(i,3)=cmin; 
 break; 
 end

30 

 end 
 t0=cmin+T(4+cind)+T(7); 

end 
mm=M(N-8,3); 
end 

