Q2=perms([2,4,5,6,8]); 
T6=10*3600+1;%记录最小值 
for i=1:6 
 for j=1:120 
 T4=Q1(i,1:3);%前往哪个工序1 
 T5=Q2(j,1:3);%去往哪里工序2 
 d=dT(abs(ceil(T4(1)/2)-T3)+1);%移动 
 QT=t0+d;%移动到T41 

 QT=max(QT,T1(T4(1)));%T41 开始下料 
 VT1(1,1)=QT; 
 QT=QT+T(7-mod(T4(1),2));%T41 下料完毕 
 d=dT(abs(ceil(T4(1)/2)-ceil(T5(1)/2))+1);%移动 
